/*
 * Host-side tests for the toolbox shell's quote and substitution scanner.
 *
 * Splits each line of a table into fields with sh_unit_next and compares them
 * with what a reference POSIX shell (dash) made of the same line (the table is
 * generated by gen-sh-quote-cases.py). Only the word and quote rules are
 * emulated here: the variables of SH_QUOTE_VARS, field splitting on blanks,
 * and a command substitution that runs `echo`. The other users of the scanner
 * are checked to agree with those boundaries.
 *
 * SPDX-License-Identifier: Apache-2.0
 */

#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "sh-scan.h"
#include "sh-quote-cases.h"

#define MAX_TEXT 4096

struct fields {
    char text[MAX_TEXT]; /* "<f1><f2>..." */
    size_t text_len;
    int n;
    char cur[MAX_TEXT];
    size_t cur_len;
    bool has; /* the word being built exists, even if empty */
};

static void emit_word(struct fields *f)
{
    if (f->has) {
        f->n++;
        f->text[f->text_len++] = '<';
        memcpy(f->text + f->text_len, f->cur, f->cur_len);
        f->text_len += f->cur_len;
        f->text[f->text_len++] = '>';
        f->text[f->text_len] = '\0';
    }
    f->cur_len = 0;
    f->has = false;
}

static void put(struct fields *f, char c)
{
    f->cur[f->cur_len++] = c;
    f->has = true;
}

static const char *var_value(const char *name, size_t n)
{
    if (n == 1 && *name == 'A')
        return "x y";
    if (n == 1 && *name == 'C')
        return " a  b ";
    if (n == 1 && *name == 'D')
        return "p*q";
    return "";
}

/* Add a value: whole when quoted, else split on blanks, where an empty
 * expansion adds nothing.
 */
static void add_value(struct fields *f, const char *v, size_t n, bool quoted)
{
    if (quoted) {
        f->has = true;
        for (size_t i = 0; i < n; i++)
            put(f, v[i]);
        return;
    }
    for (size_t i = 0; i < n; i++) {
        if (v[i] == ' ' || v[i] == '\t' || v[i] == '\n')
            emit_word(f);
        else
            put(f, v[i]);
    }
}

static void split(const char *line, struct fields *f);

/* The output of `echo ARGS` for a substitution body, else NULL. */
static bool run_echo(const char *body, size_t len, char *out)
{
    char *text = strndup(body, len);
    struct fields inner = {0};
    const char *p;
    int ok = 0;

    p = text;
    while (*p == ' ')
        p++;
    if (!strncmp(p, "echo", 4) && (p[4] == ' ' || p[4] == '\0')) {
        split(p + 4, &inner);
        out[0] = '\0';
        for (const char *q = inner.text; *q;) {
            const char *e = strchr(q, '>');

            if (q != inner.text)
                strcat(out, " ");
            strncat(out, q + 1, (size_t) (e - q - 1));
            q = e + 1;
        }
        ok = 1;
    }
    free(text);
    return ok;
}

static void split(const char *line, struct fields *f)
{
    struct sh_scan sc = {line, 0};
    struct sh_unit u;

    for (;;) {
        const char *at = sc.p;
        int q;
        char val[MAX_TEXT];

        sh_unit_next(&sc, &u);
        q = sc.quote;
        switch (u.kind) {
        case SH_U_END:
            emit_word(f);
            return;
        case SH_U_QOPEN:
        case SH_U_QCLOSE:
            f->has = true;
            break;
        case SH_U_ESC:
            put(f, at[1]);
            break;
        case SH_U_LIT:
            if (q == 0 && (*at == ' ' || *at == '\t'))
                emit_word(f);
            else
                put(f, *at);
            break;
        case SH_U_PAREN:
        case SH_U_BQ:
            if (run_echo(u.body, u.body_len, val))
                add_value(f, val, strlen(val), q != 0);
            break;
        case SH_U_BRACE:
        case SH_U_DOLLAR: {
            const char *name = u.kind == SH_U_BRACE ? u.body : at + 1;
            size_t n = 0;
            const char *v;

            while (name[n] == '_' || isalnum((unsigned char) name[n]))
                n++;
            if (u.kind == SH_U_DOLLAR && n == 0) {
                put(f, '$'); /* a $ with no name is literal */
                break;
            }
            v = var_value(name, n);
            add_value(f, v, strlen(v), q != 0);
            if (u.kind == SH_U_DOLLAR)
                sc.p = at + 1 + n; /* the name is not part of the unit */
            break;
        }
        case SH_U_ARITH:
            break;
        }
    }
}

static int failures;

static void fail(const char *what,
                 const char *line,
                 const char *want,
                 const char *got)
{
    printf("FAIL %s: %s\n  want %s\n  got  %s\n", what, line, want, got);
    failures++;
}

/* The unquoted ; and | an appended `;x|y` adds are found where they were put,
 * so no scanner mistakes the end of a case for something inside a quote.
 */
static void check_boundaries(const char *line)
{
    char buf[MAX_TEXT];
    size_t n = strlen(line);
    const char *at;

    snprintf(buf, sizeof(buf), "%s;x", line);
    at = sh_scan_find(buf, ";");
    if (at != buf + n)
        fail("find ;", line, "the appended ;", at ? at : "none");
    snprintf(buf, sizeof(buf), "%s |x", line);
    at = sh_scan_find(buf, "|");
    if (at != buf + n + 1)
        fail("find |", line, "the appended |", at ? at : "none");
}

/* A line of nothing but openings nests as deep as it is long: the scanner has
 * to cap it, and end the substitution as unterminated, not run out of stack.
 */
static void check_nesting(void)
{
    static char deep[20000];
    struct sh_scan sc = {deep, 0};
    struct sh_unit u;

    for (size_t i = 0; i + 2 < sizeof deep; i += 2)
        memcpy(deep + i, "$(", 2);
    sh_unit_next(&sc, &u);
    if (u.kind != SH_U_PAREN || u.closed || sc.p != deep + strlen(deep))
        fail("deep nesting", "$($($(...", "an unterminated substitution",
             "something else");
}

/* Where a $( ... ) ends: a ) in a comment or in a case pattern is not its
 * close. What a POSIX shell (dash) makes of each text is in the comment.
 */
static void check_groups(void)
{
    static const struct {
        const char *text;
        bool closed;
        const char *body;
    } cases[] = {
        /* the comment runs to the newline, so the ) before it is not a close */
        {"$(echo a # )\n x) y", true, "echo a # )\n x"},
        {"$(echo a # )", false, "echo a # )"},
        {"$(echo a#b) y", true, "echo a#b"},
        {"$(echo '#' ) y", true, "echo '#' "},
        {"$(case x in x) echo hi;; esac) y", true,
         "case x in x) echo hi;; esac"},
        {"$(case x in (x|y) echo hi;; esac) y", true,
         "case x in (x|y) echo hi;; esac"},
        {"$(case x in a) case y in b) :;; esac;; esac) y", true,
         "case x in a) case y in b) :;; esac;; esac"},
        {"$(echo $(case x in x) :;; esac)) y", true,
         "echo $(case x in x) :;; esac)"},
        {"$(case x in x) :\n;;\n y) :;;\nesac\n) z", true,
         "case x in x) :\n;;\n y) :;;\nesac\n"},
        /* case is only a word here, not a command */
        {"$(echo case x in) y", true, "echo case x in"},
        {"$( (echo a) ) y", true, " (echo a) "},
        {"$(case x in x) echo hi", false, "case x in x) echo hi"},
    };

    for (size_t i = 0; i < sizeof cases / sizeof *cases; i++) {
        struct sh_scan sc = {cases[i].text, 0};
        struct sh_unit u;
        char got[MAX_TEXT];

        sh_unit_next(&sc, &u);
        snprintf(got, sizeof got, "%.*s", (int) u.body_len, u.body);
        if (u.kind != SH_U_PAREN || u.closed != cases[i].closed ||
            strcmp(got, cases[i].body))
            fail("group", cases[i].text, cases[i].body, got);
    }
}

/* Where a case command that starts a text ends: just past its esac, with the
 * case commands of its arms inside it, or NULL when it never closes.
 */
static void check_case_end(void)
{
    static const struct {
        const char *text;
        const char *rest; /* what follows the esac, or NULL: not closed */
    } cases[] = {
        {"case a in a) echo x;; esac; echo y", "; echo y"},
        {"case a in a) echo x;; esac", ""},
        {"case a in a) case b in b) echo x;; esac;; esac", ""},
        {"case a in a) case b in b) echo x;; esac;; z) y;; esac; z", "; z"},
        {"case a in a) case b in b) echo x;; esac; echo t;; esac >f", " >f"},
        {"case a in a) echo \"esac\";; esac", ""},
        {"case a in a) echo esac;; esac", ""},
        {"case a in a) echo $(case b in b) :;; esac);; esac;", ";"},
        {"case a in a) echo x;;", NULL},
        {"case a in a) case b in b) echo x;; esac;;", NULL},
        {"case a in a) echo x;; esac)", ")"},
    };

    for (size_t i = 0; i < sizeof cases / sizeof *cases; i++) {
        const char *end = sh_scan_case_end(cases[i].text);

        if (!cases[i].rest ? end != NULL : (!end || strcmp(end, cases[i].rest)))
            fail("case end", cases[i].text, cases[i].rest ? cases[i].rest : "NULL",
                 end ? end : "NULL");
    }
}

int main(void)
{
    int host = 0;

    check_nesting();
    check_groups();
    check_case_end();

    for (size_t i = 0; i < sizeof(sh_quote_cases) / sizeof(*sh_quote_cases);
         i++) {
        struct fields f = {0};
        char got[MAX_TEXT + 16];

        if (!sh_quote_cases[i].host)
            continue;
        host++;
        split(sh_quote_cases[i].line, &f);
        snprintf(got, sizeof(got), "%d%s", f.n, f.text);
        if (strcmp(got, sh_quote_cases[i].fields))
            fail("fields", sh_quote_cases[i].line, sh_quote_cases[i].fields,
                 got);
        check_boundaries(sh_quote_cases[i].line);
    }
    if (host < 150) {
        printf("FAIL only %d host cases\n", host);
        failures++;
    }
    printf("sh-scan-test: %d cases, %d failures\n", host, failures);
    return failures != 0;
}
